# Step 9: Initial Screens

Create `app/index.tsx`:

```tsx
import { useEffect } from "react";
import { View, ActivityIndicator } from "react-native";
import { router } from "expo-router";
import { useAuth } from "../src/hooks/useAuth";

export default function IndexScreen() {
  const { session, loading } = useAuth();

  useEffect(() => {
    if (loading) return;

    if (session) {
      router.replace("/home");
    } else {
      router.replace("/sign-in");
    }
  }, [session, loading]);

  return (
    <View className="flex-1 items-center justify-center bg-white">
      <ActivityIndicator />
    </View>
  );
}
```

Create `app/sign-in.tsx`:

```tsx
import { useState } from "react";
import { View, Text, TextInput, Pressable, Alert } from "react-native";
import { Link, router } from "expo-router";
import { supabase } from "../src/lib/supabase";

export default function SignInScreen() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);

  async function handleSignIn() {
    try {
      setSubmitting(true);

      const { error } = await supabase.auth.signInWithPassword({
        email,
        password
      });

      if (error) {
        Alert.alert("Sign in failed", error.message);
        return;
      }

      router.replace("/home");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <View className="flex-1 justify-center bg-white px-6">
      <Text className="mb-8 text-3xl font-bold text-black">Sign in</Text>

      <TextInput
        className="mb-3 rounded-xl border border-gray-300 px-4 py-3"
        placeholder="Email"
        autoCapitalize="none"
        keyboardType="email-address"
        value={email}
        onChangeText={setEmail}
      />

      <TextInput
        className="mb-5 rounded-xl border border-gray-300 px-4 py-3"
        placeholder="Password"
        secureTextEntry
        value={password}
        onChangeText={setPassword}
      />

      <Pressable
        className="rounded-xl bg-black px-4 py-4"
        onPress={handleSignIn}
        disabled={submitting}
      >
        <Text className="text-center font-semibold text-white">
          {submitting ? "Signing in..." : "Sign in"}
        </Text>
      </Pressable>

      <Link href="/sign-up" className="mt-5 text-center text-blue-600">
        Create an account
      </Link>
    </View>
  );
}
```

